const OWNER_ID = 5;
const AUSBILDUNG_GRUPPEN = [2];

// Formular "KI-Entwurf neu erstellen": nur die angegebenen Ticketnummern, egal in welchem Status oder von wem zuletzt beantwortet.
const angefordert = String($('Von Haupt-Workflow aufgerufen').first().json.tickets || '').split(/[^0-9]+/).filter(Boolean);
if (angefordert.length > 0) {
  const gefunden = $input.all().filter(({ json: ticket }) => angefordert.includes(String(ticket.number)));
  const fehlend = angefordert.filter((nr) => !gefunden.some(({ json }) => String(json.number) === nr));
  if (fehlend.length > 0) console.log(`Angeforderte Tickets nicht gefunden: ${fehlend.join(', ')}`);
  if (gefunden.length === 0) throw new Error(`Keines der angeforderten Tickets gefunden: ${angefordert.join(', ')}`);
  return gefunden;
}

const SPRACHNACHRICHT = /^\s*(re:\s*|aw:\s*|fwd?:\s*|wg:\s*)*neue sprachnachricht von\b/i;

return $input.all().filter(({ json: ticket }) => {
  if (SPRACHNACHRICHT.test(String(ticket.title || ''))) return false;
  const eigenes = ticket.owner_id === OWNER_ID && [1, 2, 3, 6].includes(ticket.state_id);
  const ausbildung = [1, 2, 3, 6].includes(ticket.state_id) && AUSBILDUNG_GRUPPEN.includes(ticket.group_id);
  return eigenes || ausbildung;
});

const OWNER_ID = 5;
const AUSBILDUNG_GRUPPEN = [2];
// Vom Formular angeforderte Tickets werden auch dann neu bearbeitet, wenn schon ein KI-Entwurf oder eine Team-Antwort vorliegt.
const angefordert = String($('Von Haupt-Workflow aufgerufen').first().json.tickets || '').split(/[^0-9]+/).filter(Boolean);
const MAX_PAYLOAD_BYTES = 90000;
const MAX_MAIL_CHARS = 40000;
const MAX_CONTEXT_CHARS = 4000;
// Erkennt KI-Notizen an der ID in der Signatur. Die älteren Merkmale bleiben für bereits vorhandene Notizen erkannt.
const KI_MARKIERUNG = /ID-IT-xi8klGKdh8|Deutsche Lebens-Rettungs-Gesellschaft\s+Landesverband Rheinland-Pfalz|KI-Entwurf \(automatisch erstellt\)|Interne Hinweise zum KI-Entwurf/;

function stripHtml(html) {
  return String(html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function textOf(article) {
  return /html/i.test(article.content_type || '') ? stripHtml(article.body) : String(article.body || '').trim();
}

function dateOf(article) {
  return String(article.created_at || '').replace('T', ' ').slice(0, 16);
}

const ergebnis = [];

$input.all().forEach((item, index) => {
  const { articles, ...ticket } = item.json;
  const erzwungen = angefordert.includes(String(ticket.number));
  const all = (articles || [])
    .filter((a) => a.sender !== 'System')
    .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)) || a.id - b.id);

  const oeffentlich = all.filter((a) => !a.internal);
  const letzte = oeffentlich[oeffentlich.length - 1];
  if (!erzwungen && letzte && letzte.sender === 'Agent') {
    console.log(`Ticket #${ticket.number}: Team hat bereits geantwortet, übersprungen`);
    return;
  }

  if (!erzwungen && [3, 6].includes(ticket.state_id) && !oeffentlich.some((a) => a.sender === 'Agent')) {
    console.log(`Ticket #${ticket.number}: wartet auf Erinnerung oder Schließen, Kunde hat nicht geantwortet, übersprungen`);
    return;
  }

  const context = all
    .filter((a) => a.internal && /^\s*Kontext:/i.test(textOf(a)))
    .map((a) => textOf(a).replace(/^\s*Kontext:\s*/i, ''))
    .join('\n\n')
    .slice(0, MAX_CONTEXT_CHARS);

  const mails = all.filter((a) => !a.internal && textOf(a));
  const lastCustomer = [...mails].reverse().find((a) => a.sender === 'Customer');
  const target = lastCustomer || mails[mails.length - 1];
  if (!target) {
    console.log(`Ticket #${ticket.number}: keine E-Mail zum Beantworten gefunden, übersprungen`);
    return;
  }

  // Nur eine KI-Notiz, die neuer ist als die letzte Kunden-Mail, zählt: Antwortet der Kunde danach, wird das Ticket neu bearbeitet.
  if (!erzwungen && all.some((a) => a.internal && a.id > target.id && KI_MARKIERUNG.test(textOf(a)))) {
    console.log(`Ticket #${ticket.number}: KI-Entwurf liegt bereits vor, übersprungen`);
    return;
  }

  const history = mails
    .filter((a) => a.id !== target.id)
    .map((a) => ({ from: a.from || 'unbekannt', date: dateOf(a), text: textOf(a) }));

  const payload = {
    // Ausbildung lädt nur das Firmenwissen "alle" und "ausbildung" (kein PsG, nichts anderes).
    profile: AUSBILDUNG_GRUPPEN.includes(ticket.group_id) ? 'ausbildung' : undefined,
    context,
    history,
    mail: {
      from: target.from || 'unbekannt',
      date: dateOf(target),
      subject: target.subject || ticket.title,
      text: textOf(target).slice(0, MAX_MAIL_CHARS),
    },
  };

  let preTrimmed = 0;
  while (Buffer.byteLength(JSON.stringify(payload), 'utf8') > MAX_PAYLOAD_BYTES && payload.history.length > 0) {
    payload.history.shift();
    preTrimmed += 1;
  }
  if (preTrimmed > 0) {
    console.log(`Ticket #${ticket.number}: ${preTrimmed} ältere Mail(s) vor dem Aufruf gekürzt (Payload-Limit ${MAX_PAYLOAD_BYTES} Byte)`);
  }

  ergebnis.push({
    json: {
      ticket,
      modus: ticket.owner_id === OWNER_ID ? 'entwurf' : 'notiz',
      erzwungen,
      replyTo: target.reply_to || target.from || '',
      messageId: target.message_id || '',
      payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
      historyCount: payload.history.length,
      preTrimmed,
    },
    pairedItem: { item: index },
  });
});

return ergebnis;

const eingabe = $('LLM-Eingabe bauen').item.json;
