  : '';

return { json: { ticket, modus: eingabe.modus, replyTo: eingabe.replyTo, messageId: eingabe.messageId, entwurf, entwurfHtml, notizHtml, hinweise, hinweiseHtml, anhaenge, kurslinkHinweise, kurslinkHinweiseB64: Buffer.from(JSON.stringify({ hints: kurslinkHinweise, context: kurslinkKontext })).toString('base64'), warnings: parsed.warnings, stats: parsed.stats } };

const basis = $('Antwortentwurf extrahieren').item.json;
const escapeHtml = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const KURSLINK_TAG = /\[KURSLINK:\s*([^\]]*)\]/g;

let parsed = null;
if (basis.kurslinkHinweise.length > 0) {
  try {
    parsed = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
  } catch (err) {
    parsed = null;
  }
}

const auditZeilen = [];
const platzhalter = (text) => {
  const t = `[BITTE PRÜFEN: ${text}]`;
  return { html: escapeHtml(t), plain: t };
};
// Entscheidung trifft cli.js kurslink (status link | ignoriert | unklar). Ohne gültige Antwort wird nie ein Link geraten.
const decisions = basis.kurslinkHinweise.map((hint, idx) => {
  const result = parsed && parsed.ok ? parsed.results[idx] : null;
  if (!result || !result.status) {
    auditZeilen.push(`Kurslink-Nachschlag fehlgeschlagen für „${escapeHtml(hint)}“`);
    return platzhalter(`Upload-Link für ${hint}`);
  }
  if (result.status === 'link') {
    auditZeilen.push(`Kurslink automatisch eingefügt: ${escapeHtml(result.entry.kursart)} ${escapeHtml(result.entry.code)} (${escapeHtml(result.grund)})`);
    const link = escapeHtml(result.entry.url);
    return { html: `<a href="${link}">${link}</a>`, plain: result.entry.url };
  }
  if (result.status === 'ignoriert') {
    auditZeilen.push(`Kurslink nicht eingefügt: ${escapeHtml(result.grund)} – Links gibt es automatisch erst ab 2027`);
    return platzhalter(`Upload-Link für ${result.kursart || hint} von Hand einfügen (${result.grund})`);
  }
  auditZeilen.push(`Kurslink nicht eindeutig: ${escapeHtml(result.kursart || hint)} – ${escapeHtml(result.grund)}`);
  return platzhalter(`Upload-Link für ${result.kursart || hint}: Kurs nicht eindeutig`);
});

function einfuegen(text, isHtml) {
  if (!decisions.length) return text;
  let i = 0;
  return text.replace(KURSLINK_TAG, () => {
    const d = decisions[i];
    i += 1;
    return isHtml ? d.html : d.plain;
  });
}

const entwurf = einfuegen(basis.entwurf, false);
const entwurfHtml = einfuegen(basis.entwurfHtml, true);
const notizHtml = einfuegen(basis.notizHtml, true);
const hinweiseHtml = basis.hinweiseHtml + (auditZeilen.length
  ? '<p><b>Kurslink-Automatik</b></p><ul>' + auditZeilen.map((z) => '<li>' + z + '</li>').join('') + '</ul>'
  : '');

return { json: { ...basis, entwurf, entwurfHtml, notizHtml, hinweiseHtml } };

