  'Ablage: ' + art,
  'Antwort an: ' + (e.replyTo || 'unbekannt'),
  '',
  'Antwort der KI:',
  '',
  antwort,
];
if (e.hinweise.length > 0) {
  zeilen.push('', 'Interne Hinweise:', ...e.hinweise.map((h) => '- ' + h));
}
const abschnitte = [
  felder([['Ticket', '#' + t.number], ['Antwort an', e.replyTo || 'unbekannt'], ['Ablage', art]]),
  knopf('Ticket in Zammad öffnen', link, FARBEN.indigo),
  box(absaetze(antwort), FARBEN.indigo, 'Antwort der KI'),
];
if (e.hinweise.length > 0) abschnitte.push(box(liste(e.hinweise), FARBEN.amber, 'Interne Hinweise'));
const html = layout({
  label: 'Zammad · KI-Antwort',
  farbe: FARBEN.indigo,
  titel: 'Ticket #' + t.number + ': ' + t.title,
  badge: entwurf ? 'Entwurf wartet auf Freigabe' : 'Interne Notiz',
  vorschau: antwort.split('\n')[0],
  abschnitte,
});
return { json: { mailAn: MAIL_AN, mailVon: MAIL_VON, betreff: 'KI-Antwort zu Ticket #' + t.number + ': ' + t.title, text: mitId(zeilen.join('\n')), html } };

const e = $('Kurslinks in Entwurf einfügen').item.json;
const norm = (t) => String(t).toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss').replace(/[^a-z]/g, '');
const BEKANNT = [{ schluessel: 'selbsterklaerung', pfad: '/home/node/.n8n/anhaenge/Selbsterklaerung_zum_Gesundheitszustand.pdf', name: 'Selbsterklaerung_zum_Gesundheitszustand.pdf' }];
const treffer = BEKANNT.find((a) => e.anhaenge.some((h) => norm(h).includes(a.schluessel)));
if (!treffer) throw new Error('Unbekannter Anhang: ' + e.anhaenge.join(', '));
const { execFileSync } = require('child_process');
const daten = execFileSync('cat', [treffer.pfad], { maxBuffer: 50 * 1024 * 1024 });
const binary = await this.helpers.prepareBinaryData(daten, treffer.name, 'application/pdf');
return { json: { formId: 'n8n-' + require('crypto').randomUUID(), anhang: treffer.name }, binary: { File: binary } };
